72	/// Returns (name-scoped claiming-ecosystem set, complete unfiltered native-key list)
73	/// for one path's own `list` of (ecosystem, declared-id) pairs. The first is filtered
74	/// to entries whose declared name equals `primary_id.name()`; the second is not filtered.
75	fn compute_claiming_ecosystems_and_native_keys(
76	    list: &[(Ecosystem, PackageId)],
77	    primary_id: &PackageId,
78	) -> (BTreeSet<Ecosystem>, Vec<(Ecosystem, String)>) {
79	    let claiming = list
80	        .iter()
81	        .filter(|(_, id)| id.name() == primary_id.name())
82	        .map(|(eco, _)| *eco)
83	        .collect();
84	    let native_keys = list.iter().map(|(eco, id)| (*eco, id.name().to_string())).collect();
85	    (claiming, native_keys)
86	}
