98	/// Returns true iff `paths.len() > 1` AND every distinct pair of paths in `paths`
99	/// has disjoint claiming-ecosystem sets in `claiming_ecosystems`.
100	///
101	/// Overlapping claiming sets indicate a true duplicate package error (handled
102	/// separately during graph construction), NOT a valid multi-ecosystem promotion.
103	#[cfg(test)]
104	fn is_promoted_bare_name(paths: &[PathBuf], claiming_ecosystems: &BTreeMap<PathBuf, BTreeSet<Ecosystem>>) -> bool {
105	    if paths.len() <= 1 {
106	        return false;
107	    }
108	    let mut seen = BTreeSet::new();
109	    for path in paths {
110	        if let Some(ecos) = claiming_ecosystems.get(path) {
111	            for eco in ecos {
112	                if !seen.insert(*eco) {
113	                    return false;
114	                }
115	            }
116	        }
117	    }
118	    true
119	}
