121	/// A manifest the graph build could not resolve. Dropping it silently would shrink the release without a trace, so it
122	/// is reported as an error-level diagnostic that makes loading the workspace for planning fail.
123	fn unresolved(manifest: &Path, what: &str, cause: impl std::fmt::Display) -> Diagnostic {
124	    // `./package.json` and `package.json` are one manifest.
125	    let manifest: PathBuf = manifest
126	        .components()
127	        .filter(|component| !matches!(component, std::path::Component::CurDir))
128	        .collect();
129	    let manifest = manifest.as_path();
130	    Diagnostic {
131	        code: DiagnosticCode::ManifestUnresolved,
132	        severity: DiagnosticSeverity::Error,
133	        message: format!("`{}`: could not {what}: {cause}", manifest.display()),
134	        package: None,
135	        path: Some(manifest.to_path_buf()),
136	        escalated_by: None,
137	        governed_by: None,
138	    }
139	}
