197	fn discover<L: ProjectLocator>(
198	    root: &Path,
199	    locator: &L,
200	    manifest_cache: &RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
201	    ctx: &OpenContext<'_>,
202	    diagnostics: &mut Vec<Diagnostic>,
203	) -> Result<Discovered, GraphError> {
204	    let (projects, platform_candidates) = locator.projects_and_platform_candidates()?;
205	
206	    // The locator already parsed each manifest, so reuse `proj.id`.
207	    let mut by_path: BTreeMap<PathBuf, Vec<(Ecosystem, PackageId)>> = BTreeMap::new();
208	    for proj in &projects {
209	        by_path
210	            .entry(proj.path.clone())
211	            .or_default()
212	            .push((proj.ecosystem, proj.id.clone()));
213	    }
214	
215	    let attached_platforms = platform_owners(root, &by_path, &platform_candidates, manifest_cache, ctx, diagnostics);
216	    Ok(Discovered {
217	        by_path,
218	        attached_platforms,
219	    })
220	}
