242	/// The order-dependent identity assignment: whether a path's identity is bare or ecosystem-prefixed depends on the
243	/// names seen in earlier paths, so this is one incremental pass that owns all of its bookkeeping.
244	struct IdentityAssigner<'a> {
245	    manifest_cache: &'a RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
246	    ctx: &'a OpenContext<'a>,
247	    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
248	    index: IdentityIndex,
249	    claiming_ecosystems: BTreeMap<PathBuf, BTreeSet<Ecosystem>>,
250	    // Every (ecosystem, native name) any path declares, anywhere in that path's
251	    // manifest list -- not only its primary name -- belongs to exactly one directory.
252	    native_owner: BTreeMap<(Ecosystem, String), PathBuf>,
253	    path_native_keys: BTreeMap<PathBuf, Vec<(Ecosystem, String)>>,
254	    path_platform_keys: BTreeMap<PathBuf, Vec<String>>,
255	    primary_ecosystems: BTreeMap<PathBuf, Ecosystem>,
256	    promoted_siblings: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>>,
257	    unresolved: Vec<Diagnostic>,
258	}
259	
260	impl<'a> IdentityAssigner<'a> {
261	    fn new(manifest_cache: &'a RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>, ctx: &'a OpenContext<'a>) -> Self {
262	        IdentityAssigner {
263	            manifest_cache,
264	            ctx,
265	            package_manifest_decls: BTreeMap::new(),
266	            index: IdentityIndex::default(),
267	            claiming_ecosystems: BTreeMap::new(),
268	            native_owner: BTreeMap::new(),
269	            path_native_keys: BTreeMap::new(),
270	            path_platform_keys: BTreeMap::new(),
271	            primary_ecosystems: BTreeMap::new(),
272	            promoted_siblings: BTreeMap::new(),
273	            unresolved: Vec::new(),
274	        }
275	    }
276	
277	    fn assign(&mut self, rel_path: PathBuf, mut list: Vec<(Ecosystem, PackageId)>) -> Result<(), GraphError> {
278	        // Explicit precedence: Cargo (0) > Npm (1) > Pypi (2) > others.
279	        // Do NOT rely on enum discriminant order -- sort by this named
280	        // priority function so the precedence survives future variant
281	        // additions to `Ecosystem`.
282	        list.sort_by_key(|a| a.0.primary_priority());
283	
284	        // E100 whenever any (ecosystem, native name) this path declares -- primary
285	        // or not -- is already owned by a different path; names both. Checked before
286	        // any promotion bookkeeping so a dual-manifest directory's non-primary name
287	        // (e.g. an npm sibling of a Cargo-primary package) is covered too, not just
288	        // each path's own primary name.
289	        if let Some((eco, id)) = list.iter().find(|(eco, id)| {
290	            self.native_owner
291	                .get(&(*eco, id.name().to_string()))
292	                .is_some_and(|p| *p != rel_path)
293	        }) {
294	            let owner_path = self.native_owner[&(*eco, id.name().to_string())].clone();
295	            return Err(GraphError::DuplicatePackage {
296	                id: id.clone(),
297	                paths: vec![owner_path, rel_path],
298	            });
299	        }
300	        for (eco, id) in &list {
301	            self.native_owner
302	                .insert((*eco, id.name().to_string()), rel_path.clone());
303	        }
304	
305	        let mut primary_id = list[0].1.clone();
306	        let (this_claiming, this_native_keys) = compute_claiming_ecosystems_and_native_keys(&list, &primary_id);
307	        self.claiming_ecosystems.insert(rel_path.clone(), this_claiming.clone());
308	        self.path_native_keys.insert(rel_path.clone(), this_native_keys);
309	        self.primary_ecosystems.insert(rel_path.clone(), list[0].0);
310	
311	        let mut branch_ii_promoted = false;
312	        if self.promoted_siblings.contains_key(primary_id.name()) {
313	            let this_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
314	            let promoted_id = PackageId::Prefixed {
315	                ecosystem: self.primary_ecosystems[&rel_path],
316	                name: primary_id.name().to_string(),
317	            };
318	            self.promoted_siblings
319	                .entry(primary_id.name().to_string())
320	                .or_default()
321	                .push((promoted_id.clone(), this_set));
322	            primary_id = promoted_id;
323	            branch_ii_promoted = true;
324	        }
325	
326	        if !branch_ii_promoted {
327	            self.index
328	                .bare
329	                .insert(primary_id.name().to_string(), primary_id.clone());
330	        }
331	
332	        let mut decls = Vec::new();
333	        for (eco, id) in &list {
334	            let (fmt, filename) = match eco {
335	                Ecosystem::Cargo => (ManifestFormat::CargoToml, "Cargo.toml"),
336	                Ecosystem::Npm => (ManifestFormat::PackageJson, "package.json"),
337	                Ecosystem::Pypi => (ManifestFormat::PyprojectToml, "pyproject.toml"),
338	                _ => (ManifestFormat::PackageJson, "package.json"),
339	            };
340	            let manifest_rel = rel_path.join(filename);
341	            let canonical_decl = match ManifestDecl::new(manifest_rel.clone(), ManifestRole::Canonical, fmt) {
342	                Ok(decl) => {
343	                    decls.push(decl.clone());
344	                    Some(decl)
345	                }
346	                Err(error) => {
347	                    self.unresolved
348	                        .push(unresolved(&manifest_rel, "declare its manifest", error));
349	                    None
350	                }
351	            };
352	            // For napi platform packages (os + cpu constraints in package.json),
353	            // also push a Platform-role decl so release derivation can route them
354	            // as platform publishes instead of main packages. Reuses
355	            // the canonical decl's manifest handle via the shared
356	            // `manifest_cache` (`npm_role()`) instead of a second, raw
357	            // `fs::read` of the same package.json -- the handle opened here
358	            // is the same one `publish_targets`/`iter_dependencies` reuse
359	            // further down.
360	            if *eco == Ecosystem::Npm {
361	                let opened = canonical_decl
362	                    .as_ref()
363	                    .map(|decl| open_cached(self.manifest_cache, decl, self.ctx));
364	                let manifest = match opened {
365	                    Some(Ok(manifest)) => Some(manifest),
366	                    Some(Err(error)) => {
367	                        self.unresolved.push(unresolved(
368	                            &manifest_rel,
369	                            "open its manifest to read its platform role",
370	                            error,
371	                        ));
372	                        None
373	                    }
374	                    None => None,
375	                };
376	                let role = manifest
377	                    .and_then(|m| m.npm_role())
378	                    .map(|npm_role| match npm_role {
379	                        callisto_manifests::NpmRole::Platform { platform, arch, abi } => {
380	                            ManifestRole::Platform { platform, arch, abi }
381	                        }
382	                    })
383	                    .unwrap_or(ManifestRole::Canonical);
384	                if let ManifestRole::Platform { .. } = role {
385	                    match ManifestDecl::new(manifest_rel.clone(), role.clone(), fmt) {
386	                        Ok(platform_decl) => decls.push(platform_decl),
387	                        Err(error) => {
388	                            self.unresolved
389	                                .push(unresolved(&manifest_rel, "declare its platform manifest", error))
390	                        }
391	                    }
392	                    // `id` is this manifest's own npm identity, resolved from its
393	                    // own `name` field -- distinct from `primary_id` whenever a
394	                    // higher-priority ecosystem (Cargo) shares this directory.
395	                    // Config authors reference the platform package by
396	                    // its own name in `[[fixed-group]] members`, so that must be
397	                    // the index key; `primary_id` is who it belongs to.
398	                    self.index
399	                        .platform
400	                        .insert(id.name().to_string(), (primary_id.clone(), manifest_rel, role));
401	                    self.path_platform_keys
402	                        .entry(rel_path.clone())
403	                        .or_default()
404	                        .push(id.name().to_string());
405	                }
406	            }
407	            self.index
408	                .native
409	                .insert((*eco, id.name().to_string()), primary_id.clone());
410	            if id.name() == primary_id.name() {
411	                self.index
412	                    .prefixed
413	                    .insert((*eco, id.name().to_string()), primary_id.clone());
414	            }
415	        }
416	
417	        let current_decls = decls.clone();
418	        if let Some((existing_path, existing_decls)) = self
419	            .package_manifest_decls
420	            .insert(primary_id.clone(), (rel_path.clone(), decls))
421	        {
422	            self.promotion_rekey(primary_id, existing_path, existing_decls, rel_path, current_decls);
423	        }
424	        Ok(())
425	    }
426	
427	    /// A second path just claimed the bare name `primary_id`, so both paths are promoted to ecosystem-prefixed ids
428	    /// and every key already stored under the stale bare id is re-keyed.
429	    fn promotion_rekey(
430	        &mut self,
431	        primary_id: PackageId,
432	        existing_path: PathBuf,
433	        existing_decls: Vec<ManifestDecl>,
434	        rel_path: PathBuf,
435	        current_decls: Vec<ManifestDecl>,
436	    ) {
437	        // Both paths' claiming ecosystems are guaranteed disjoint here: an
438	        // overlap would already have failed at the native_owner check above.
439	        let name = primary_id.name().to_string();
440	        // STALE-KEY REWRITE location (4): re-key package_manifest_decls under
441	        // each path's own newly-promoted Prefixed id, sourcing each path's own
442	        // decls -- captured via the `existing_decls` returned by `insert` above
443	        // and the `current_decls` clone taken before `insert` overwrote the map,
444	        // never via a `.get(&primary_id)` lookup after the fact (a lookup miss
445	        // there would silently substitute an empty Vec -- the
446	        // manifests-bleed bug).
447	        let existing_id = PackageId::Prefixed {
448	            ecosystem: self.primary_ecosystems[&existing_path],
449	            name: name.clone(),
450	        };
451	        let current_id = PackageId::Prefixed {
452	            ecosystem: self.primary_ecosystems[&rel_path],
453	            name: name.clone(),
454	        };
455	        self.package_manifest_decls
456	            .insert(existing_id.clone(), (existing_path.clone(), existing_decls));
457	        self.package_manifest_decls
458	            .insert(current_id.clone(), (rel_path.clone(), current_decls));
459	        self.package_manifest_decls.remove(&primary_id);
460	        // STALE-KEY REWRITE location (1): once a bare name is promoted,
461	        // it MUST NOT remain in index.bare.
462	        self.index.bare.remove(&name);
463	        // STALE-KEY REWRITE location (2): update index.native values
464	        // for all native keys declared by either path so they map to
465	        // their path's newly-promoted Prefixed id, not the stale primary_id.
466	        if let Some(keys) = self.path_native_keys.get(&existing_path) {
467	            for key in keys {
468	                self.index.native.insert(key.clone(), existing_id.clone());
469	            }
470	        }
471	        if let Some(keys) = self.path_native_keys.get(&rel_path) {
472	            for key in keys {
473	                self.index.native.insert(key.clone(), current_id.clone());
474	            }
475	        }
476	        // STALE-KEY REWRITE location (3)/(5): update index.prefixed values
477	        // for the primary identities so they point to the newly-promoted
478	        // Prefixed id rather than the pre-promotion primary_id.
479	        for eco in self
480	            .claiming_ecosystems
481	            .get(&existing_path)
482	            .cloned()
483	            .unwrap_or_default()
484	        {
485	            self.index.prefixed.insert((eco, name.clone()), existing_id.clone());
486	        }
487	        for eco in self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default() {
488	            self.index.prefixed.insert((eco, name.clone()), current_id.clone());
489	        }
490	        // STALE-KEY REWRITE location (6): update index.platform's owner-id
491	        // component for every platform manifest declared under either path,
492	        // so a platform sibling co-located with a promoted owner keeps
493	        // pointing at that owner's newly-promoted Prefixed id rather than
494	        // the stale pre-promotion primary_id.
495	        if let Some(keys) = self.path_platform_keys.get(&existing_path) {
496	            for key in keys {
497	                if let Some((_, manifest_rel, role)) = self.index.platform.get(key).cloned() {
498	                    self.index
499	                        .platform
500	                        .insert(key.clone(), (existing_id.clone(), manifest_rel, role));
501	                }
502	            }
503	        }
504	        if let Some(keys) = self.path_platform_keys.get(&rel_path) {
505	            for key in keys {
506	                if let Some((_, manifest_rel, role)) = self.index.platform.get(key).cloned() {
507	                    self.index
508	                        .platform
509	                        .insert(key.clone(), (current_id.clone(), manifest_rel, role));
510	                }
511	            }
512	        }
513	        let existing_set = self
514	            .claiming_ecosystems
515	            .get(&existing_path)
516	            .cloned()
517	            .unwrap_or_default();
518	        let current_set = self.claiming_ecosystems.get(&rel_path).cloned().unwrap_or_default();
519	        self.promoted_siblings
520	            .entry(name.clone())
521	            .or_default()
522	            .extend([(existing_id, existing_set), (current_id, current_set)]);
523	    }
524	
525	    /// After every path is assigned, so each owner's id is final (post-promotion).
526	    fn attach_platforms(&mut self, attached_platforms: BTreeMap<PathBuf, (PathBuf, String, ManifestRole)>) {
527	        for (platform_dir, (owner_dir, name, role)) in attached_platforms {
528	            let manifest_rel = platform_dir.join("package.json");
529	            let owner = self.package_manifest_decls.iter_mut().find(|(_, (path, decls))| {
530	                *path == owner_dir && decls.iter().any(|d| d.format == ManifestFormat::PackageJson)
531	            });
532	            let Some((owner_id, (_, decls))) = owner else {
533	                self.unresolved.push(unresolved(
534	                    &manifest_rel,
535	                    "attach it to its owner",
536	                    format!("`{}` has no npm manifest to own it", owner_dir.display()),
537	                ));
538	                continue;
539	            };
540	            match ManifestDecl::new(manifest_rel.clone(), role.clone(), ManifestFormat::PackageJson) {
541	                Ok(decl) => {
542	                    decls.push(decl);
543	                    self.index.platform.insert(name, (owner_id.clone(), manifest_rel, role));
544	                }
545	                Err(error) => self
546	                    .unresolved
547	                    .push(unresolved(&manifest_rel, "declare its platform manifest", error)),
548	            }
549	        }
550	    }
551	
552	    fn finish(self) -> Identified {
553	        Identified {
554	            package_manifest_decls: self.package_manifest_decls,
555	            index: self.index,
556	            unresolved: self.unresolved,
557	        }
558	    }
